  p jsonb; current_policy record; ddl text; missing integer:=0; changed integer:=0;
  body text; new_body text; definition text; body_hash text; f oid;
BEGIN
  FOR p IN SELECT * FROM jsonb_array_elements(v_plan->'policies') LOOP
    SELECT qual,with_check,roles,permissive,cmd INTO current_policy FROM pg_policies
