          AND current_policy.with_check IS NOT DISTINCT FROM v->>'with_check') THEN
      IF NOT EXISTS(SELECT 1 FROM pg_proc h
        CROSS JOIN jsonb_array_elements(p->'equivalent_guarded_variants') v
        WHERE h.oid=to_regprocedure('public.is_admin_or_cofounder(uuid)')
