          AND current_policy.with_check IS NOT DISTINCT FROM v->>'with_check'
          AND encode(sha256(convert_to(h.prosrc,'UTF8')),'hex')=v->>'helper_sha256') THEN
        RAISE EXCEPTION 'ADMIN_POLICY_GUARDED_HELPER_DRIFT';
      END IF;
      CONTINUE; -- Preserve this reviewed pre-existing active-admin/ownership implementation.
    END IF;
    IF current_policy.qual IS DISTINCT FROM p->>'qual'
       OR current_policy.with_check IS DISTINCT FROM p->>'with_check' THEN
      RAISE EXCEPTION 'ADMIN_POLICY_SOURCE_DRIFT: %.% %',p->>'schemaname',p->>'tablename',p->>'policyname';
    END IF;
    ddl:=format('ALTER POLICY %I ON %I.%I',p->>'policyname',p->>'schemaname',p->>'tablename');
    IF p->>'after_qual' IS NOT NULL THEN ddl:=ddl||' USING ('||(p->>'after_qual')||')';END IF;
    IF p->>'after_check' IS NOT NULL THEN ddl:=ddl||' WITH CHECK ('||(p->>'after_check')||')';END IF;
    EXECUTE ddl;
    changed:=changed+1;
  END LOOP;
  f:=to_regprocedure('public.trg_fn_protect_user_sensitive_fields()');
  IF f IS NULL THEN RAISE EXCEPTION 'SENSITIVE_PROFILE_TRIGGER_MISSING';END IF;
  SELECT prosrc INTO body FROM pg_proc WHERE oid=f;
  body_hash:=encode(sha256(convert_to(body,'UTF8')),'hex');
  IF body_hash IS DISTINCT FROM v_plan->'trigger'->>'after_sha256' THEN
    IF body_hash IS DISTINCT FROM v_plan->'trigger'->>'before_sha256' THEN RAISE EXCEPTION 'SENSITIVE_PROFILE_TRIGGER_SOURCE_DRIFT';END IF;
    new_body:=replace(body,v_plan->'trigger'->>'old_fragment',v_plan->'trigger'->>'new_fragment');
    IF encode(sha256(convert_to(new_body,'UTF8')),'hex') IS DISTINCT FROM v_plan->'trigger'->>'after_sha256' THEN RAISE EXCEPTION 'SENSITIVE_PROFILE_TRIGGER_PATCH_HASH';END IF;
    definition:=pg_get_functiondef(f);
    IF length(definition)-length(replace(definition,body,''))<>length(body) THEN RAISE EXCEPTION 'SENSITIVE_PROFILE_TRIGGER_AMBIGUOUS';END IF;
    EXECUTE replace(definition,body,new_body);
  END IF;
  RAISE NOTICE 'ACTIVE_ADMIN_POLICIES changed=%, absent=%; sensitive-profile actor guard checked',changed,missing;
END;
$restrict$;
